type fakeUsers struct {
	mu    sync.Mutex
	users map[UserID]User
}
func (f *fakeUsers) Save(u User) { f.mu.Lock(); defer f.mu.Unlock(); f.users[u.ID] = u }
func (f *fakeUsers) Find(id UserID) (User, bool) {
	f.mu.Lock(); defer f.mu.Unlock()
	u, ok := f.users[id]
	return u, ok
}
var _ UserRepository = (*fakeUsers)(nil)
